demo2_in = [[6,0,0,2,3,0,0,0],[0,6,0,0,2,3,0,0],[0,0,6,0,0,2,3,0],[3,0,0,6,0,0,2,3],[8,3,0,0,6,0,0,2],[0,8,3,0,0,6,0,0],[0,0,8,3,0,0,6,0],[0,0,0,8,3,0,0,6]]
demo2_out = [[6,8,3,2,3,6,8,3],[3,6,8,3,2,3,6,8],[2,3,6,8,3,2,3,6],[3,2,3,6,8,3,2,3],[8,3,2,3,6,8,3,2],[6,8,3,2,3,6,8,3],[3,6,8,3,2,3,6,8],[2,3,6,8,3,2,3,6]]
from collections import defaultdict
dvals=defaultdict(set)
for r,row in enumerate(demo2_out):
 for c,v in enumerate(row): dvals[c-r].add(v)
print(sorted((d,vs) for d,vs in dvals.items()))
# map diagonals nonzeros input
nonz=defaultdict(set)
for r,row in enumerate(demo2_in):
 for c,v in enumerate(row):
  if v: nonz[c-r].add(v)
print('input', sorted((d,vs) for d,vs in nonz.items()))
